// Resolve Device Brand Identity & Logo (2-Pass High-Precision Matcher)
function getDeviceBrand(d) {
  const name = (d.custom_name || "").toLowerCase();
  const vendor = (d.vendor || "").toLowerCase();
  const host = (d.hostname || "").toLowerCase();

  const brandRules = [
    { keys: ["home assistant", "hass"], name: "Home Assistant", svg: BRAND_SVGS.homeAssistant },
    { keys: ["raspberry", "raspi"], name: "Raspberry Pi", svg: BRAND_SVGS.raspberryPi },
    { keys: ["nvidia", "shield"], name: "NVIDIA", svg: BRAND_SVGS.nvidia },
    { keys: ["truenas", "ixsystems"], name: "TrueNAS", svg: BRAND_SVGS.truenas },
    { keys: ["unraid", "castleserver"], name: "Unraid", svg: BRAND_SVGS.unraid },
    { keys: ["sonoff", "ewelink"], name: "Sonoff", svg: BRAND_SVGS.sonoff },
    { keys: ["tuya", "smart life"], name: "Tuya", svg: BRAND_SVGS.tuya },
    { keys: ["xiaomi", "aspirador", "mijia", "roborock"], name: "Xiaomi", svg: BRAND_SVGS.xiaomi },
    { keys: ["samsung", "galaxy"], name: "Samsung", svg: BRAND_SVGS.samsung },
    { keys: ["amazon", "alexa", "echo"], name: "Amazon Alexa", svg: BRAND_SVGS.amazon },
    { keys: ["philips", "hue"], name: "Philips Hue", svg: BRAND_SVGS.philips },
    { keys: ["chromecast", "google", "nest"], name: "Google", svg: BRAND_SVGS.google },
    { keys: ["apple", "macbook", "iphone", "ipad", "apple tv", "airplay"], name: "Apple", svg: BRAND_SVGS.apple },
    { keys: ["playstation", "sony"], name: "PlayStation / Sony", svg: BRAND_SVGS.playstation },
    { keys: ["msi"], name: "MSI", svg: BRAND_SVGS.msi },
    { keys: ["huawei"], name: "Huawei", svg: BRAND_SVGS.huawei },
    { keys: ["intel", "windows", "pc desktop"], name: "Intel / Windows", svg: BRAND_SVGS.intel },
    { keys: ["asus"], name: "ASUS", svg: BRAND_SVGS.asus },
    { keys: ["tp-link"], name: "TP-Link", svg: BRAND_SVGS.tplink },
    { keys: ["arcadyan", "altice", "meo", "gateway", "router principal"], name: "MEO", svg: BRAND_SVGS.meo },
    { keys: ["lg", "innotek"], name: "LG", svg: BRAND_SVGS.lg },
    { keys: ["espressif", "esp32", "esp8266"], name: "Espressif", svg: BRAND_SVGS.espressif },
    { keys: ["sonos"], name: "Sonos", svg: BRAND_SVGS.sonos },
    { keys: ["nintendo", "switch"], name: "Nintendo", svg: BRAND_SVGS.nintendo },
    { keys: ["synology", "diskstation"], name: "Synology", svg: BRAND_SVGS.synology },
    { keys: ["shelly"], name: "Shelly", svg: BRAND_SVGS.shelly },
    { keys: ["dell"], name: "Dell", svg: BRAND_SVGS.dell },
    { keys: ["ubiquiti", "unifi"], name: "Ubiquiti UniFi", svg: BRAND_SVGS.ubiquiti },
    { keys: ["hp ", "hewlett", "hp-"], name: "HP", svg: BRAND_SVGS.hp },
    { keys: ["formuler", "aloys", "iptv"], name: "Formuler IPTV", svg: BRAND_SVGS.formuler },
    { keys: ["privado", "aleat"], name: "Dispositivo Privado (Wi-Fi)", svg: BRAND_SVGS.private }
  ];

  // Pass 1: Prioritize explicit custom_name (user-assigned or verified device identity)
  if (name) {
    for (const rule of brandRules) {
      if (rule.keys.some(k => name.includes(k))) {
        return { name: rule.name, svg: rule.svg };
      }
    }
  }

  // Pass 2: Check vendor, hostname, or combined text
  const combined = `${name} ${vendor} ${host}`;
  for (const rule of brandRules) {
    if (rule.keys.some(k => combined.includes(k))) {
      return { name: rule.name, svg: rule.svg };
    }
  }

  if (d.device_type === "printer" || combined.includes("impressora") || combined.includes("printer") || combined.includes("canon") || combined.includes("epson") || combined.includes("brother")) {
    return { name: "Impressora", svg: BRAND_SVGS.printer };
  }

  // Fallback to category icon
  const cat = CATEGORIES[d.device_type] || CATEGORIES.unknown;
  return {
    name: cat.label,
    svg: `<i data-lucide="${cat.icon}" class="w-full h-full"></i>`
  };
}

// Privacy Masking Helpers
function maskIp(ip) {
  if (!state.privacyMode || !ip) return ip;
  const parts = ip.split(".");
  if (parts.length === 4) return `${parts[0]}.${parts[1]}.${parts[2]}.•••`;
  return ip;
}

function maskMac(mac) {
  if (!state.privacyMode || !mac) return mac;
  const parts = mac.split(":");
  if (parts.length === 6) return `${parts[0]}:${parts[1]}:${parts[2]}:••:••:••`;
  return mac;
}

function togglePrivacyMode() {
  state.privacyMode = !state.privacyMode;
  localStorage.setItem("netpulse_privacy_mode", state.privacyMode ? "true" : "false");
  updatePrivacyIcon();
  renderDevices();
  updateNetworkHeader();
  showToast(state.privacyMode ? "Modo Privacidade Ativado (IPs e MACs ocultados)" : "Modo Privacidade Desativado", "info");
}

function updatePrivacyIcon() {
  const icon = document.getElementById("privacy-icon");
  const btn = document.getElementById("btn-privacy-toggle");
  if (!icon || !btn) return;
  if (state.privacyMode) {
    icon.setAttribute("data-lucide", "eye-off");
    btn.classList.add("text-cyan-400", "border-cyan-500/50");
  } else {
    icon.setAttribute("data-lucide", "eye");
    btn.classList.remove("text-cyan-400", "border-cyan-500/50");
  }
  if (window.lucide) lucide.createIcons();
}

// Authentication & Session Protection
function showAuthModal() {
  const modal = document.getElementById("modal-auth");
  if (modal) {
    modal.classList.remove("hidden");
    const inp = document.getElementById("auth-input-password");
    if (inp) {
      inp.value = "";
      setTimeout(() => inp.focus(), 100);
    }
  }
}

function hideAuthModal() {
  const modal = document.getElementById("modal-auth");
  if (modal) modal.classList.add("hidden");
}

function togglePasswordVisibility() {
  const inp = document.getElementById("auth-input-password");
  const icon = document.getElementById("auth-eye-icon");
  if (!inp || !icon) return;
  if (inp.type === "password") {
    inp.type = "text";
    icon.setAttribute("data-lucide", "eye-off");
  } else {
    inp.type = "password";
    icon.setAttribute("data-lucide", "eye");
  }
  if (window.lucide) lucide.createIcons();
}

async function handleLoginSubmit(e) {
  e.preventDefault();
  const inp = document.getElementById("auth-input-password");
  const btn = document.getElementById("auth-btn-submit");
  const errMsg = document.getElementById("auth-error-msg");
  if (!inp || !btn) return;

  btn.disabled = true;
  btn.innerHTML = `<i data-lucide="loader" class="w-4 h-4 animate-spin inline mr-1.5"></i> A verificar...`;
  if (window.lucide) lucide.createIcons();
  if (errMsg) errMsg.classList.add("hidden");

  try {
    const res = await fetch("/api/auth/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ password: inp.value })
    });
    const data = await res.json();
    if (res.ok && data.success) {
      state.isAuthenticated = true;
      hideAuthModal();
      showToast("Painel desbloqueado com sucesso!", "success");
      initAppData();
    } else {
      if (errMsg) {
        errMsg.textContent = data.error || "Palavra-passe incorreta.";
        errMsg.classList.remove("hidden");
      }
      inp.focus();
      inp.select();
    }
  } catch (err) {
    if (errMsg) {
      errMsg.textContent = "Erro ao contactar o servidor.";
      errMsg.classList.remove("hidden");
    }
  } finally {
    btn.disabled = false;
    btn.textContent = "Desbloquear Painel";
  }
}

async function checkAuthStatus() {
  try {
    const res = await fetch("/api/auth/status");
    const data = await res.json();
    if (data.db_engine) {
      const badge = document.getElementById("header-db-badge");
      const name = document.getElementById("header-db-name");
      if (badge && name) {
        badge.classList.remove("hidden");
        name.textContent = data.db_engine;
      }
    }
    state.authRequired = !!data.auth_required;
    state.isAuthenticated = !!data.authenticated;
    if (state.authRequired && !state.isAuthenticated) {
      showAuthModal();
      return false;
    }
    hideAuthModal();
    return true;
  } catch (err) {
    return true;
  }
}

function initAppData() {
  setViewMode(state.viewMode);
  updateSortIndicators();
  syncSortSelect();
  initLatencyChart();
  fetchDevices();
  fetchRouterLatency();
  fetchSpeedtestHistory();
  fetchAlerts();
  fetchAgents();
  fetchAgentLogs();
}

// Initialize Application
document.addEventListener("DOMContentLoaded", async () => {
  if (window.lucide) {
    lucide.createIcons();
  }
  updatePrivacyIcon();
  setViewMode(state.viewMode);
  const isAuth = await checkAuthStatus();
  if (isAuth) {
    initAppData();
  }

  // Periodic background refresh
  setInterval(() => {
    if (!state.isAuthenticated) return;
    if (state.activeTab === "latency" || state.activeTab === "devices") {
      fetchRouterLatency(true);
    } else if (state.activeTab === "agents") {
      fetchAgents(true);
      fetchAgentLogs(true);
    }
  }, 4000);
});

// Switch Main Navigation Tabs
function switchTab(tabId) {
  state.activeTab = tabId;

  // Toggle Tab Content (Desktop & Mobile Sync)
  ["devices", "latency", "speedtest", "alerts", "agents"].forEach(t => {
    const el = document.getElementById(`tab-content-${t}`);
    const btn = document.getElementById(`tab-btn-${t}`);
    const mBtn = document.getElementById(`m-tab-${t}`);
    if (el) el.classList.toggle("hidden", t !== tabId);
    if (btn) btn.classList.toggle("active", t === tabId);
    if (mBtn) {
      mBtn.classList.toggle("active", t === tabId);
      mBtn.classList.toggle("text-cyan-400", t === tabId);
      mBtn.classList.toggle("text-slate-400", t !== tabId);
    }
  });

  if (tabId === "latency") {
    fetchRouterLatency();
  } else if (tabId === "speedtest") {
    fetchSpeedtestHistory();
  } else if (tabId === "alerts") {
    fetchAlerts();
  } else if (tabId === "agents") {
    fetchAgents();
    fetchAgentLogs();
  }

  if (window.lucide) lucide.createIcons();
}

// Toggle View Mode (Table vs Grid)
function setViewMode(mode) {
  state.viewMode = mode;
  try {
    localStorage.setItem("netpulse_view_mode", mode);
  } catch (e) {}

  const btnTable = document.getElementById("btn-view-table");
  const btnGrid = document.getElementById("btn-view-grid");
  const tableContainer = document.getElementById("container-table-view");
  const gridContainer = document.getElementById("container-grid-view");

  if (btnTable) btnTable.classList.toggle("bg-slate-800", mode === "table");
  if (btnGrid) btnGrid.classList.toggle("bg-slate-800", mode === "grid");
  if (tableContainer) tableContainer.classList.toggle("hidden", mode !== "table");
  if (gridContainer) gridContainer.classList.toggle("hidden", mode !== "grid");
  renderDevices();
}

// Fetch Devices from API
async function fetchDevices() {
  try {
    const res = await fetch("/api/devices");
    if (res.status === 401) {
      showAuthModal();
      return;
    }
    const data = await res.json();
    state.devices = data.devices || [];
    if (data.network_info) {
      state.networkInfo = data.network_info;
      updateNetworkHeader();
    }
    renderKPIs();
    renderCategoryPills();
    renderDevices();
    const lastUp = document.getElementById("last-updated-text");
    if (lastUp) lastUp.textContent = `Atualizado: ${new Date().toLocaleTimeString()}`;
  } catch (err) {
    console.error("Erro ao carregar dispositivos:", err);
  }
}

function updateNetworkHeader() {
  const gwEl = document.getElementById("info-gateway");
  const locEl = document.getElementById("info-localip");
  const ifaceEl = document.getElementById("header-iface");
  const subnetEl = document.getElementById("header-subnet");

  if (gwEl) gwEl.textContent = maskIp(state.networkInfo.gateway_ip || "192.168.1.1");
  if (locEl) locEl.textContent = maskIp(state.networkInfo.local_ip || "127.0.0.1");
  if (ifaceEl) ifaceEl.textContent = state.networkInfo.interface || "en0";
  if (subnetEl && state.networkInfo.gateway_ip) {
    const prefix = state.networkInfo.gateway_ip.split(".").slice(0, 3).join(".");
    subnetEl.textContent = state.privacyMode ? "Sub-rede: Protegida (Modo Privacidade)" : `Sub-rede: ${prefix}.0/24`;
  }
}

// Trigger Full Subnet Scan
async function triggerScan(quick = false) {
  if (state.isScanning) return;
  state.isScanning = true;

  const btn = document.getElementById("btn-scan");
  const icon = document.getElementById("scan-icon");
  const text = document.getElementById("scan-text");

  btn.disabled = true;
  icon.classList.add("spin-scanning");
  text.textContent = "A varrer...";

  try {
    const res = await fetch("/api/scan", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ quick })
    });
    const data = await res.json();
    state.devices = data.devices || [];
    if (data.gateway_ip) {
      state.networkInfo.gateway_ip = data.gateway_ip;
      state.networkInfo.local_ip = data.local_ip;
      state.networkInfo.interface = data.interface;
      updateNetworkHeader();
    }
    renderKPIs();
    renderCategoryPills();
    renderDevices();
    fetchAlerts();
  } catch (err) {
    console.error("Falha no varrimento de rede:", err);
  } finally {
    state.isScanning = false;
    btn.disabled = false;
    icon.classList.remove("spin-scanning");
    text.textContent = "Varrer Rede";
  }
}

// Render Top KPI Stats
function renderKPIs() {
  const total = state.devices.length;
  const newCount = state.devices.filter(d => d.is_new).length;

  document.getElementById("kpi-total-devices").textContent = total;
  document.getElementById("kpi-new-devices").textContent = newCount;
  document.getElementById("tab-count-devices").textContent = total;
}

// Render Category Filter Pills
function renderCategoryPills() {
  const container = document.getElementById("category-pills");
  if (!container) return;

  // Calculate counts per category
  const counts = { all: state.devices.length };
  Object.keys(CATEGORIES).forEach(k => {
    if (k !== "all") counts[k] = 0;
  });

  state.devices.forEach(d => {
    const cat = d.device_type || "unknown";
    if (counts[cat] !== undefined) counts[cat]++;
    else counts["unknown"]++;
  });

  let html = "";
  Object.entries(CATEGORIES).forEach(([key, meta]) => {
    const isActive = state.selectedCategory === key;
    const count = counts[key] || 0;
    html += `
      <button onclick="selectCategory('${key}')" class="cat-pill ${meta.colorClass || ''} ${isActive ? 'active' : ''} flex items-center gap-1.5 px-3 py-1.5 rounded-xl whitespace-nowrap">
        <i data-lucide="${meta.icon}" class="w-3.5 h-3.5"></i>
        <span>${meta.label}</span>
        <span class="ml-1 px-1.5 py-0.2 text-[10px] font-mono rounded-full bg-slate-800/80 ${isActive ? 'text-white' : 'text-slate-400'}">${count}</span>
      </button>
    `;
  });

  container.innerHTML = html;
  if (window.lucide) lucide.createIcons();
}

function selectCategory(catKey) {
  state.selectedCategory = catKey;
  renderCategoryPills();
  renderDevices();
}

function handleSearch(val) {
  state.searchQuery = (val || "").trim().toLowerCase();
  renderDevices();
}

// Numerical IP Comparator
function compareIps(ipA, ipB) {
  const aParts = (ipA || "").split(".").map(n => parseInt(n, 10) || 0);
  const bParts = (ipB || "").split(".").map(n => parseInt(n, 10) || 0);
  for (let i = 0; i < 4; i++) {
    const diff = (aParts[i] || 0) - (bParts[i] || 0);
    if (diff !== 0) return diff;
  }
  return 0;
}

// Table Header Click Handler for Column Sorting
function handleHeaderSort(column) {
  if (state.sortColumn === column) {
    state.sortDirection = state.sortDirection === "asc" ? "desc" : "asc";
  } else {
    state.sortColumn = column;
    state.sortDirection = "asc";
  }
  syncSortSelect();
  updateSortIndicators();
  renderDevices();
}

// Dropdown Sort Change Handler
function handleSortSelect(val) {
  const parts = (val || "ip_asc").split("_");
  state.sortColumn = parts[0];
  state.sortDirection = parts[1] || "asc";
  updateSortIndicators();
  renderDevices();
}

function syncSortSelect() {
  const select = document.getElementById("sort-select");
  if (!select) return;
  const targetVal = `${state.sortColumn}_${state.sortDirection}`;
  for (let opt of select.options) {
    if (opt.value === targetVal) {
      select.value = targetVal;
      return;
    }
  }
}

function updateSortIndicators() {
  const cols = ["name", "ip", "mac", "vendor", "category", "ports"];
  cols.forEach(col => {
    const indicator = document.getElementById(`sort-indicator-${col}`);
    const th = indicator ? indicator.closest("th") : null;
    if (!indicator) return;
    if (state.sortColumn === col) {
      indicator.textContent = state.sortDirection === "asc" ? "▲" : "▼";
      indicator.className = "text-[10px] text-cyan-400 font-bold";
      if (th) th.classList.add("sorted");
    } else {
      indicator.textContent = "↕";
      indicator.className = "text-[10px] text-slate-500";
      if (th) th.classList.remove("sorted");
    }
  });
}

// Filter and Sort Devices based on Category, Search & Column Ordering
function getFilteredDevices() {
  const filtered = state.devices.filter(dev => {
    // Category filter
    if (state.selectedCategory !== "all") {
      if ((dev.device_type || "unknown") !== state.selectedCategory) {
        return false;
      }
    }
    // Search query filter
    if (state.searchQuery) {
      const q = state.searchQuery;
      const ip = (dev.ip || "").toLowerCase();
      const mac = (dev.mac || "").toLowerCase();
      const name = (dev.custom_name || dev.hostname || "").toLowerCase();
      const vendor = (dev.vendor || "").toLowerCase();
      if (!ip.includes(q) && !mac.includes(q) && !name.includes(q) && !vendor.includes(q)) {
        return false;
      }
    }
    return true;
  });

  // Apply Sorting
  filtered.sort((a, b) => {
    let cmp = 0;
    switch (state.sortColumn) {
      case "ip":
        cmp = compareIps(a.ip, b.ip);
        break;
      case "name": {
        const nameA = (a.custom_name || a.hostname || a.vendor || "").toLowerCase();
        const nameB = (b.custom_name || b.hostname || b.vendor || "").toLowerCase();
        cmp = nameA.localeCompare(nameB);
        break;
      }
      case "mac":
        cmp = (a.mac || "").localeCompare(b.mac || "");
        break;
      case "vendor":
        cmp = (a.vendor || "").toLowerCase().localeCompare((b.vendor || "").toLowerCase());
        break;
      case "category": {
        const catA = (CATEGORIES[a.device_type]?.label || a.device_type || "").toLowerCase();
        const catB = (CATEGORIES[b.device_type]?.label || b.device_type || "").toLowerCase();
        cmp = catA.localeCompare(catB);
        break;
      }
      case "ports": {
        const pA = Array.isArray(a.open_ports) ? a.open_ports.length : 0;
        const pB = Array.isArray(b.open_ports) ? b.open_ports.length : 0;
        cmp = pA - pB;
        break;
      }
      default:
        cmp = compareIps(a.ip, b.ip);
    }
    return state.sortDirection === "asc" ? cmp : -cmp;
  });

  return filtered;
}

// Helper to get category badge UI with distinct category theme
function getCategoryBadge(type) {
  const cat = CATEGORIES[type] || CATEGORIES.unknown;
  return `
    <span class="category-badge ${cat.colorClass}">
      <i data-lucide="${cat.icon}" class="w-3 h-3"></i>
      <span>${cat.label}</span>
    </span>
  `;
}

// Glassmorphic Toast Notifications
function showToast(message, type = "info") {
  const container = document.getElementById("toast-container");
  if (!container) return;

  const icons = {
    success: "check-circle",
    info: "info",
    warning: "alert-triangle",
    error: "alert-octagon"
  };

  const toast = document.createElement("div");
  toast.className = `glass-toast toast-${type}`;
  toast.innerHTML = `
    <div class="glass-toast-icon">
      <i data-lucide="${icons[type] || 'info'}" class="w-4 h-4"></i>
    </div>
    <span class="flex-1 text-slate-100">${escapeHtml(message)}</span>
  `;

  container.appendChild(toast);
  if (window.lucide) lucide.createIcons();

  requestAnimationFrame(() => {
    toast.classList.add("show");
  });

  setTimeout(() => {
    toast.classList.remove("show");
    toast.classList.add("hide");
    setTimeout(() => toast.remove(), 300);
  }, 3200);
}

// Copy to clipboard helper with toast feedback
async function copyToClipboard(text, label = "Texto") {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
    } else {
      const textarea = document.createElement("textarea");
      textarea.value = text;
      textarea.style.position = "fixed";
      textarea.style.opacity = "0";
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
    }
    showToast(`${label} copiado: ${text}`, "success");
  } catch (err) {
    showToast(`Erro ao copiar ${label}`, "error");
  }
}

