// Live Ping Single Device
async function pingDevice(deviceId, ip, btnEl) {
  const originalHtml = btnEl.innerHTML;
  btnEl.innerHTML = `<i data-lucide="loader" class="w-3.5 h-3.5 animate-spin"></i>`;
  if (window.lucide) lucide.createIcons();

  try {
    const res = await fetch(`/api/devices/${deviceId}/ping`);
    const data = await res.json();
    if (data.ping && data.ping.avg_ms !== null) {
      btnEl.innerHTML = `<span class="text-cyan-400 font-bold">${data.ping.avg_ms}ms</span>`;
    } else {
      btnEl.innerHTML = `<span class="text-slate-500">Timeout</span>`;
    }
  } catch (e) {
    btnEl.innerHTML = `<span class="text-rose-400">Erro</span>`;
  }
}

// Port Scan Single Device
async function scanDevicePorts(deviceId, ip) {
  const modal = document.getElementById("modal-ports");
  const content = document.getElementById("modal-ports-content");
  const subtitle = document.getElementById("modal-ports-subtitle");

  subtitle.textContent = `Varrimento em curso para o IP: ${maskIp(ip)}...`;
  content.innerHTML = `
    <div class="p-8 text-center text-slate-400 space-y-3">
      <div class="inline-block animate-spin w-8 h-8 border-2 border-cyan-500 border-t-transparent rounded-full"></div>
      <p class="text-xs">A auditar portas TCP e serviços comuns...</p>
    </div>
  `;
  modal.classList.remove("hidden");

  try {
    const res = await fetch(`/api/devices/${deviceId}/scan-ports`, { method: "POST" });
    const data = await res.json();
    const ports = data.open_ports || [];
    subtitle.textContent = `IP: ${maskIp(ip)} • ${ports.length} portas detetadas`;

    if (ports.length === 0) {
      content.innerHTML = `
        <div class="p-6 text-center text-slate-400 space-y-2">
          <i data-lucide="shield-check" class="w-8 h-8 mx-auto text-emerald-400"></i>
          <p class="font-medium text-white">Nenhuma porta pública aberta detetada.</p>
          <p class="text-xs">O dispositivo tem a firewall local ativada ou não expõe serviços TCP diretos.</p>
        </div>
      `;
    } else {
      content.innerHTML = ports.map(p => {
        let riskColor = "text-cyan-400 bg-cyan-950/60 border-cyan-800";
        if (p.risk === "high") riskColor = "text-rose-400 bg-rose-950/60 border-rose-800";
        if (p.risk === "medium") riskColor = "text-amber-400 bg-amber-950/60 border-amber-800";

        return `
          <div class="p-3 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-between">
            <div class="flex items-center gap-3">
              <span class="font-mono font-bold text-sm text-cyan-300">:${p.port}</span>
              <div>
                <span class="font-semibold text-white text-xs">${escapeHtml(p.service)}</span>
                <p class="text-[11px] text-slate-400">${escapeHtml(p.description)}</p>
              </div>
            </div>
            <span class="px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${riskColor}">${p.risk}</span>
          </div>
        `;
      }).join("");
    }
    fetchDevices();
  } catch (err) {
    content.innerHTML = `<div class="p-4 text-rose-400 text-xs text-center">Falha ao auditar portas: ${err}</div>`;
  }
  if (window.lucide) lucide.createIcons();
}

function closePortsModal() {
  document.getElementById("modal-ports").classList.add("hidden");
}

// Edit Device Modal
function openEditModal(deviceId) {
  const dev = state.devices.find(d => d.id === deviceId);
  if (!dev) return;

  document.getElementById("edit-device-id").value = dev.id;
  document.getElementById("edit-custom-name").value = dev.custom_name || "";
  document.getElementById("edit-device-type").value = dev.device_type || "unknown";
  document.getElementById("edit-device-notes").value = dev.notes || "";
  document.getElementById("modal-edit-device").classList.remove("hidden");
}

function closeEditModal() {
  document.getElementById("modal-edit-device").classList.add("hidden");
}

async function saveDeviceDetails() {
  const id = document.getElementById("edit-device-id").value;
  const custom_name = document.getElementById("edit-custom-name").value.trim();
  const device_type = document.getElementById("edit-device-type").value;
  const notes = document.getElementById("edit-device-notes").value.trim();

  try {
    await fetch(`/api/devices/${id}/edit`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ custom_name, device_type, notes })
    });
    closeEditModal();
    fetchDevices();
  } catch (err) {
    alert("Erro ao gravar alterações: " + err);
  }
}

async function trustDevice(deviceId) {
  try {
    await fetch(`/api/devices/${deviceId}/trust`, { method: "POST" });
    fetchDevices();
    fetchAlerts();
  } catch (err) {
    console.error(err);
  }
}

// Router Latency & WAN Health
async function fetchRouterLatency(silent = false) {
  try {
    const res = await fetch("/api/router-latency");
    const data = await res.json();

    const gwMs = data.router_latency?.avg_ms;
    const wanMs = data.internet_latency?.avg_ms;
    const jitter = data.router_latency?.jitter_ms;

    const kpiRouter = document.getElementById("kpi-router-latency");
    if (kpiRouter && gwMs !== null && gwMs !== undefined) {
      kpiRouter.textContent = gwMs;
    }
    const diagGw = document.getElementById("diag-gw-ms");
    if (diagGw && gwMs !== null && gwMs !== undefined) {
      diagGw.textContent = `${gwMs} ms`;
    }

    const kpiWan = document.getElementById("kpi-wan-latency");
    if (kpiWan && wanMs !== null && wanMs !== undefined) {
      kpiWan.textContent = wanMs;
    }

    const kpiJitter = document.getElementById("kpi-router-jitter");
    if (kpiJitter && jitter !== undefined && jitter !== null) {
      kpiJitter.textContent = `${jitter} ms`;
    }
    const diagJitter = document.getElementById("diag-jitter");
    if (diagJitter && jitter !== undefined && jitter !== null) {
      diagJitter.textContent = `${jitter} ms`;
    }

    if (data.health_assessment) {
      const kpiHealth = document.getElementById("kpi-router-health");
      if (kpiHealth) kpiHealth.textContent = data.health_assessment;
      const diagBadge = document.getElementById("diag-gw-badge");
      if (diagBadge) diagBadge.textContent = data.health_assessment;
    }

    if (data.history && state.latencyChart) {
      updateLatencyChart(data.history);
    }
  } catch (err) {
    if (!silent) console.error("Erro na leitura de latência:", err);
  }
}

// Chart.js Latency Setup
